/// Lines shaped like Claude Code's own log, with only the fields Transcript reads and some it must skip.
private let log = [
    #"{"type":"permission-mode","permissionMode":"default"}"#,
    #"{"parentUuid":null,"type":"user","uuid":"u1","cwd":"/Users/me/shelf","message":{"role":"user","content":"the order test fails one run in ten"}}"#,
    #"{"parentUuid":"u1","type":"user","uuid":"u2","isMeta":true,"message":{"role":"user","content":"Caveat: the messages below were generated by the user"}}"#,
    #"{"parentUuid":"u2","type":"user","uuid":"u3","message":{"role":"user","content":"<command-name>/clear</command-name>"}}"#,
    #"{"parentUuid":"u3","type":"assistant","uuid":"a1","cwd":"/Users/me/shelf","message":{"role":"assistant","content":[{"type":"thinking","thinking":"hmm"},{"type":"text","text":"The test compares two links saved in the same millisecond."}]}}"#,
    #"{"parentUuid":"a1","type":"assistant","uuid":"a2","cwd":"/Users/me/shelf","message":{"role":"assistant","content":[{"type":"tool_use","name":"Bash","input":{"command":"npm test","description":"Run the tests"}}]}}"#,
    #"{"parentUuid":"a2","type":"user","uuid":"u4","message":{"role":"user","content":[{"type":"tool_result","content":"12 passed"}]}}"#,
    #"{"parentUuid":"u4","type":"assistant","uuid":"a3","cwd":"/Users/me/shelf","message":{"role":"assistant","content":[{"type":"tool_use","name":"Edit","input":{"file_path":"/Users/me/shelf/tests/store.test.ts","old_string":"await sleep(1)","new_string":"const clock = fixedClock()\nconst store = createStore({ clock })"}}]}}"#,
    #"{"parentUuid":"a3","type":"assistant","uuid":"a4","isSidechain":true,"message":{"role":"assistant","content":[{"type":"text","text":"from a subagent"}]}}"#,
    #"{"type":"api-request","payload":"{\"type\":\"user\"}"}"#,
    "not json at all",
]

private func file(_ lines: [String]) throws -> URL {
    let url = FileManager.default.temporaryDirectory.appendingPathComponent("transcript-\(UUID().uuidString).jsonl")
    try (lines.joined(separator: "\n") + "\n").write(to: url, atomically: true, encoding: .utf8)
    return url
}

